def solve(times):
    def to_minutes(time):
        h, m = map(int, time.split(':'))
        return h * 60 + m

    def to_time(minutes):
        h = minutes // 60
        m = minutes % 60
        return f"{h:02}:{m:02}"

    unique_times = sorted(set(map(to_minutes, times)))
    max_interval = 0

    for i in range(1, len(unique_times)):
        interval = unique_times[i] - unique_times[i - 1]
        if interval > max_interval:
            max_interval = interval

    last_to_first = (24 * 60 - unique_times[-1]) + unique_times[0]
    if last_to_first > max_interval:
        max_interval = last_to_first

    return to_time(max_interval)
